def numeroter_les_pieces_existantes(apps, schema_editor):
    """Donne à chaque pièce existante son numéro définitif.

    Ordre : celui de la chronologie — évènements par date, heure, puis
    identifiant ; dans un évènement, les pièces par identifiant —, puis les
    pièces liées à aucun évènement. C'est l'ordre qu'utilisait l'export.
    Le compteur du dossier reprend au dernier numéro donné.
    """
    Dossier = apps.get_model("events", "Dossier")
    Document = apps.get_model("events", "Document")
    Event = apps.get_model("events", "Event")
    for dossier in Dossier.objects.all():
        numeros = {}
        evenements = Event.objects.filter(dossier=dossier).order_by(
            "date", models.F("heure").asc(nulls_first=True), "pk")
        for evenement in evenements:
            for document in Document.objects.filter(events=evenement).order_by("pk"):
                numeros.setdefault(document.pk, len(numeros) + 1)
        for document in Document.objects.filter(dossier=dossier).order_by("pk"):
            numeros.setdefault(document.pk, len(numeros) + 1)
        for pk, numero in numeros.items():
            Document.objects.filter(pk=pk).update(numero=numero)
        Dossier.objects.filter(pk=dossier.pk).update(dernier_numero_piece=len(numeros))


